/**
 * THROWAWAY generator (never committed): renders the refused-recipient emails at the BASE commit f3ce21fe so the head
 * test (tests/report-digests-staffing-recipients.test.ts, S9 / F6) can compare its render with the PRE-CHANGE render.
 * Uses only what exists at base: renderShopDigest / renderUnifiedDigest / renderCateringDigest, composeShopSections /
 * composeCateringSections / allShopsSection, tests/fixtures/digest-v2.ts, the envelope { viewer, access }.
 * The facts are plain objects with NO `schedule` key; they are written into the golden and rendered from their
 * JSON round-trip, so the head test renders from exactly the same input bytes.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { it } from "vitest";
import type { Language } from "@/lib/i18n/types";
import { digestAccessFor, type DigestAccess } from "@/lib/report-digests-access-shared";
import {
  composeCateringSections, composeShopSections, renderCateringDigest, renderShopDigest, renderUnifiedDigest,
  type CateringFacts, type CateringLeadFact, type DigestSection, type Envelope, type ShopDayFacts,
} from "@/lib/report-digests-compose";
import { NO_ACCESS_VIEWER, type LinkViewer } from "@/lib/report-digests-links";
import { allShopsSection } from "@/lib/report-digests-v2-compose";
import { ok, unavailable, type ShopV2Facts } from "@/lib/report-digests-v2-shared";
import { v2Fixture } from "./fixtures/digest-v2";

const OUT = process.env.GOLDEN_OUT!;
const BASE = "https://ops.example.com";
const A = "aaaaaaaa-0000-4000-8000-000000000001";
const B = "bbbbbbbb-0000-4000-8000-000000000002";
const C = "cccccccc-0000-4000-8000-000000000003";
const D = "2026-10-07";
const D1 = "2026-10-08";
const SHOP_A = { id: A, name: "Shop A" };
const SHOP_B = { id: B, name: "Shop B" };

// Plain data (the same values the head fixture builds; no head code).
const LABOR = {
  totalHours: 62.5, openEntries: 0, byJob: [{ job: "Line", hours: 62.5 }],
  people: [{ employeeGuid: "g1", firstName: "Person A", hours: 8, unknownShifts: 0 }],
  unknownHoursEntries: 0, partial: false, salesPerLaborHourCents: 1500,
  overtimeAssessed: true, dayOvertimeAssessed: true, weekOvertimeAssessed: true, dayOvertime: [], weekOvertime: [],
};
function busyTomorrow(): Partial<ShopV2Facts> {
  const cutoffs = Array.from({ length: 8 }, (_, i) => ({ vendorId: `v${i}`, vendorName: `Vendor ${i}`, cutoffTime: "10:00:00", ordered: i > 0, hasDraft: false }));
  const base = v2Fixture();
  if (base.ordering.kind !== "ok") throw new Error("fixture");
  return { ordering: ok({ ...base.ordering.value, cutoffsTomorrow: cutoffs }) };
}
const BASELINES: Array<[string, Partial<ShopV2Facts>]> = [
  ["Toast labor ok", { labor: ok(LABOR as never) }],
  ["S9 (i) v.labor absent", {}],
  ["S9 (ii) unavailable('no_labor')", { labor: unavailable("no_labor") }],
];
const shopFacts = (shop: { id: string; name: string }, over: Partial<ShopV2Facts>): ShopDayFacts => ({
  location: shop, day: D, reports: [],
  receiving: { deliveries: 0, discrepant: 0, missingReceipt: 0 }, tosses: 0, storeRunsPending: 0, tasks: [], pmFindings: null,
  v2: v2Fixture({ ...busyTomorrow(), ...over }),
});
const lead = (id: string, locationId: string, eventDate: string): CateringLeadFact => ({
  id, contactName: `Customer ${id}`, company: null, eventDate, timeWindow: "11:30", headcount: 20, stage: "confirmed",
  leadSource: "phone", locationId, createdDay: "2026-10-01", followUpDate: null, externalRef: null, isDelivery: false,
  valueCents: 30000, dueCents: 0, prep: null,
});
const manyLeads = (shop: string) => [
  ...Array.from({ length: 7 }, (_, i) => lead(`${shop.slice(0, 1)}t${i}`, shop, D)),
  ...Array.from({ length: 7 }, (_, i) => lead(`${shop.slice(0, 1)}m${i}`, shop, D1)),
];
const catering: CateringFacts = {
  today: D, leads: [...manyLeads(A), ...manyLeads(B)], lostYesterdayIds: [], quotesSentYesterday: [], openQuotes: [], refundsYesterday: [],
  staff: {
    [A]: ok({ source: "stations", scheduleConnected: false, onStation: [{ firstName: "Person A", station: "Grill", source: "claimed" }] }),
    [B]: ok({ source: "stations", scheduleConnected: false, onStation: [] }),
  },
} as CateringFacts;

const rt = <T,>(x: T): T => JSON.parse(JSON.stringify(x)) as T;
const facts = rt({
  shop: Object.fromEntries(BASELINES.map(([name, over]) => [name, { A: shopFacts(SHOP_A, over), B: shopFacts(SHOP_B, over) }])),
  catering,
});
const scope = { locations: [SHOP_A, SHOP_B], includeUnassigned: false };

// The refused recipients, as BASE knows them (an access is only { viewer }; base has no delivery).
const smm: LinkViewer = { role: "social_media_mgr", level: 6, locations: [A, B] };
const other: LinkViewer = { role: "gm", level: 7, locations: [C] };
const unknownRole: LinkViewer = { role: "regional_wizard", level: 9, locations: [A, B] };
const GM_A: LinkViewer = { role: "gm", level: 7, locations: [A] };
const REFUSED: Array<[string, LinkViewer | null, DigestAccess | null]> = [
  ["a flagged social media manager", smm, digestAccessFor(smm)],
  ["a recipient at another shop", other, digestAccessFor(other)],
  ["an unknown role", unknownRole, digestAccessFor(unknownRole)],
  ["a null viewer", null, null],
  ["a null access (GM viewer)", GM_A, null],
  ["an access WITHOUT digest (a GM composed directly)", GM_A, digestAccessFor(GM_A)],
  ["no access viewer", NO_ACCESS_VIEWER, digestAccessFor(NO_ACCESS_VIEWER)],
];

const PREHEADER = /<div style="display:none;max-height:0;overflow:hidden;color:transparent;line-height:0;">([^<]*)<\/div>/;
const statuses = (sections: Array<DigestSection | null>) => sections.filter((s): s is DigestSection => s !== null).map((s) => [s.title, s.status ?? null, s.lines.length]);
// Identical renders are stored once (`bodies`); `renders` holds the index of each one's body.
const bodies: unknown[] = [];
const bodyIndex = new Map<string, number>();
const golden = (mail: { subject: string; html: string; text: string }, sections: Array<DigestSection | null>): number => {
  const body = { subject: mail.subject, preheader: PREHEADER.exec(mail.html)?.[1] ?? null, statuses: statuses(sections), html: mail.html, text: mail.text };
  const key = JSON.stringify(body);
  let i = bodyIndex.get(key);
  if (i === undefined) { i = bodies.length; bodies.push(body); bodyIndex.set(key, i); }
  return i;
};

it("generate", () => {
  const renders: Record<string, Record<string, Record<string, unknown>>> = { shop: {}, unified: {}, catering: {} };
  for (const language of ["en", "es"] as Language[]) {
    renders.shop![language] = {}; renders.unified![language] = {}; renders.catering![language] = {};
    for (const [who, viewer, access] of REFUSED) {
      const env: Envelope = { language, baseUrl: BASE, viewer, access };
      const shop: Record<string, unknown> = {};
      const unified: Record<string, unknown> = {};
      for (const [baseline] of BASELINES) {
        const pair = facts.shop[baseline] as { A: ShopDayFacts; B: ShopDayFacts };
        shop[baseline] = golden(renderShopDigest(pair.A, env), composeShopSections(pair.A, language, BASE, false, viewer, access));
        const shops = [pair.A, pair.B];
        unified[baseline] = golden(renderUnifiedDigest({ day: D, shops, notFinalized: [] }, env), [
          allShopsSection(shops, language, BASE, D, viewer, access),
          ...shops.flatMap((f) => composeShopSections(f, language, BASE, true, viewer, access)),
        ]);
      }
      renders.shop![language]![who] = shop;
      renders.unified![language]![who] = unified;
      renders.catering![language]![who] = golden(renderCateringDigest(facts.catering, scope, env), composeCateringSections(facts.catering, scope, language, BASE, viewer, access));
    }
  }
  const out = {
    note: [
      "PRE-CHANGE renders of every refused recipient's digest (plan §11.1.6 S9; PR 2 fix round F6).",
      "Rendered by the BASE commit's own code, not by the head renderer: a head render must equal these byte for byte.",
      "Generated by a throwaway vitest file run inside a clean checkout of the base commit (see `generatedBy`).",
      "The facts below are plain objects with NO schedule key; the head test renders from exactly these.",
      "`renders` maps digest / language / recipient (/ labor baseline) to an index into `bodies` (identical renders stored once).",
      "A body: subject, preheader (the hidden inbox preview), every section [title, status, line count], html, text.",
      "Regenerate only with a written reason.",
    ],
    baseSha: "f3ce21fe6eba22f1d47cea0c39f74b4977f5f200",
    generatedBy: "in a checkout of f3ce21fe: GOLDEN_OUT=<path> npx vitest run tests/zz-gen-staffing-base-goldens.test.ts (the generator is not committed; its full source is `generatorSource` below)",
    generatorSource: readFileSync(fileURLToPath(import.meta.url), "utf8"),
    baseEnvelopes: Object.fromEntries(REFUSED.map(([who, viewer, access]) => [who, { viewer, access }])),
    cateringScope: scope,
    facts,
    renders,
    bodies,
  };
  writeFileSync(OUT, JSON.stringify(out, null, 1) + "\n");
});
